src, out = sys.argv[1], sys.argv[2]
os.makedirs(out, exist_ok=True)
for f, s in SPEC.items():
    a = open(os.path.join(src, f), "rb").read()
    if hashlib.md5(a).hexdigest() != s["from"]:
        sys.exit("%s: the live file is not %s" % (f, s["from"][:8]))
    L = a.decode("utf-8").splitlines(keepends=True)
    for i1, i2, new in reversed(s["ops"]):
        L[i1:i2] = new
    b = "".join(L).encode("utf-8")
    if hashlib.md5(b).hexdigest() != s["to"]:
        sys.exit("%s: the remade file is not %s" % (f, s["to"][:8]))
    open(os.path.join(out, f), "wb").write(b)
    print(f, s["from"][:8], "->", s["to"][:8])
